css:
.ovp-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ovp-root,.ovp-root *,.ovp-root *::before,.ovp-root *::after{box-sizing:border-box}
.ovp-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ovp-root img{display:block;border:0;max-width:none}
.ovp-root > [data-node-id]{will-change:transform}
.ovp-root [hidden]{display:none!important}
.ovp-root [data-sh-theme="light"]{display:none!important}
.ovp-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.ovp-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.ovp-root .n49_2293{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;margin-bottom:-1px;place-items:start;position:relative;flex-shrink:0}
.ovp-root .n49_2294{background-color:var(--wa-point, #121634);grid-column:1;height:30px;margin-left:0;margin-top:0;position:relative;border-bottom-left-radius:15px;border-top-left-radius:15px;grid-row:1;width:150px}
.ovp-root .n49_2294::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-point, #37496c);border-radius:inherit;pointer-events:none}
.ovp-root .n49_2295{grid-column:1;height:30.566px;margin-left:0;margin-top:0.43px;position:relative;grid-row:1;width:32px}
.ovp-root .x345{position:absolute;inset:-26.17% -21.88% -22.9% -24.63%}
.ovp-root .x346{display:block;max-width:none;width:100%;height:100%}
.ovp-root .n49_2301{word-break:break-word;grid-column:1;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;margin-left:113px;margin-top:9.43px;font-style:normal;position:relative;grid-row:1;color:var(--wa-point, #a7c5df);font-size:12px;text-align:right;white-space:nowrap;width:22px}
.ovp-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.ovp-root[data-theme="light"] [data-name="Badge/Critical"] p,.ovp-root[data-theme="light"] [data-name^="status-critical"] p,.ovp-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.ovp-root[data-theme="light"] [data-name="Badge/Major"] p,.ovp-root[data-theme="light"] [data-name^="status-major"] p,.ovp-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.ovp-root[data-theme="light"] [data-name="Badge/Minor"] p,.ovp-root[data-theme="light"] [data-name^="status-minor"] p,.ovp-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.ovp-root[data-theme="light"] [data-name="Badge/Warning"] p,.ovp-root[data-theme="light"] [data-name^="status-warning"] p,.ovp-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.ovp-root[data-theme="light"] [data-name="Badge/Normal"] p,.ovp-root[data-theme="light"] [data-name^="status-normal"] p,.ovp-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.ovp-root[data-theme="light"] [data-name="Button/Ack"] p,.ovp-root[data-theme="light"] [data-name="Button/Ack All"] p,.ovp-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.ovp-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.ovp-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.ovp-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.ovp-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.ovp-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.ovp-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.ovp-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.ovp-root[data-theme="light"] :is([data-name="Symbol"],[data-name="Floor"],[data-name="Floor Layer"],[data-name="Effect"]) img{filter:brightness(1.75) saturate(.55);opacity:.7}
.ovp-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.ovp-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.ovp-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1e86f0)!important}
.ovp-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.ovp-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.ovp-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.ovp-root[data-theme="light"] :is([data-name^="Node/"],[data-name="Icons"],[data-name="Node Group"]) p{text-shadow:0 0 3px #fff,0 0 6px #fff,0 0 10px rgba(255,255,255,.9)}
.ovp-root[data-theme="light"] .n49_2294{background-color:var(--wa-bg, #eeeff4)}
.ovp-root[data-theme="light"] .n49_2301{color:var(--wa-point, #294f70)}
